"""
Validation script for pipeline outputs.
Checks that expected output files exist and are non-empty.
"""

import os
import json
import sys

OUTPUTS_DIR = "outputs"
CHECK_RESULTS = []

def check_file_exists(filepath):
    """Check if a file exists."""
    try:
        if not os.path.exists(filepath):
            return False, "File does not exist"
        return True, "File exists"
    except Exception as e:
        return False, str(e)

def check_file_non_empty(filepath):
    """Check if a file is non-empty."""
    try:
        if not os.path.exists(filepath):
            return False, "File does not exist"
        size = os.path.getsize(filepath)
        if size == 0:
            return False, "File is empty"
        return True, f"File has {size} bytes"
    except Exception as e:
        return False, str(e)

def run_checks():
    """Run all validation checks."""
    global CHECK_RESULTS

    # List of expected output files
    expected_files = [
        "outputs/t01_selected_indicators.csv",
        "outputs/t05_clean_stops.csv",
        "outputs/t08_pois_clean.csv",
        "outputs/t10_accessibility_scores.csv",
        "outputs/t13_city_clusters.csv"
    ]

