    checks = []

    for filepath in expected_files:
        exists, message = check_file_exists(filepath)
        non_empty, message = check_file_non_empty(filepath)

        # Check if file exists
        if not exists:
            checks.append({
                "check_name": f"output_exists_{filepath}",
                "passed": False,
                "message": message
            })
            continue

        # Check if file is non-empty
        if not non_empty:
            checks.append({
                "check_name": f"output_non_empty_{filepath}",
                "passed": False,
                "message": message
            })
            continue

        # Success for this file
        checks.append({
            "check_name": f"output_valid_{filepath}",
            "passed": True,
            "message": f"File exists and has content ({non_empty[0]})"
        })

    # Write validation summary JSON
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w') as f:
        json.dump(checks, f, indent=2)

    return checks

if __name__ == "__main__":
    checks = run_checks()

    # Print summary
    passed = sum(1 for c in checks if c["passed"])
    failed = len(checks) - passed
    print(f"Validation complete. {passed} passed, {failed} failed.")

    # Show failed checks
    for c in checks:
        if not c["passed"]:
            print(f"  - {c['check_name']}: {c['message']}")

    # Exit with appropriate code
    sys.exit(0 if failed == 0 else 1)
